pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzedTimestamp, uint256 fuzzedBlockNum) public {
        vm.assume(fuzzedTimestamp > 0 && fuzzedTimestamp <= type(uint64).max);
        vm.assume(fuzzedBlockNum > 0);
        vm.assume(fuzzedBlockNum % 15 != 0);
        vm.warp(fuzzedTimestamp);
        vm.roll(fuzzedBlockNum);
        address sender = address(0x1234);
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "fallback reverted unexpectedly");
        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}
